#!/usr/bin/env python3
import base64,gzip,hashlib,pathlib,sys
BASE_SHA="b1895254bf4b5d6c242185787bfb687f717bc3268eb5e0cd1955d47a0293b481"
TEST_SHA="fd67b8159f7d186ced31cd21dc5e90668ebcef277a26d6a9df25282b4694073a"
PAYLOAD=""""""
root=pathlib.Path(sys.argv[1] if len(sys.argv)>1 else ".")
path=root/"src-tauri/src/shorts_factory.rs"
old=path.read_bytes(); actual=hashlib.sha256(old).hexdigest()
if actual!=BASE_SHA: raise SystemExit(f"unexpected Shorts media-fix baseline {actual}")
new=gzip.decompress(base64.b64decode(PAYLOAD))
if hashlib.sha256(new).hexdigest()!=TEST_SHA: raise SystemExit("Shorts media test payload checksum mismatch")
path.write_bytes(new)
print("VYRON 2.1.4 Shorts media acceptance tests applied")
